<?php
// Restore AppServiceProvider to original
$appServiceFile = __DIR__ . '/../app/Providers/AppServiceProvider.php';
file_put_contents($appServiceFile, base64_decode(''));

// Patch routes/web.php
$routesFile = __DIR__ . '/../routes/web.php';
$routesContent = file_get_contents($routesFile);
$routesContent = str_replace(
    "Route::get('daily/export'",
    "Route::match(['GET', 'POST'], 'daily/export'",
    $routesContent
);
file_put_contents($routesFile, $routesContent);

// Clear route cache via Artisan
try {
    require __DIR__.'/../vendor/autoload.php';
    $app = require_once __DIR__.'/../bootstrap/app.php';
    $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class);
    $kernel->call('route:clear');
} catch (\Throwable $e) {
    // Ignore cache clear errors if not applicable
}

echo "<h1 style='color:green; text-align:center; margin-top: 50px;'>Đã khôi phục hệ thống và sửa lỗi xuất Excel thành công!</h1>";
echo "<div style='text-align:center;'><a href='/reports/daily' style='font-size: 20px;'>Bấm vào đây để quay lại trang Lịch học</a></div>";
